开始实现V5 Schema写入端。按以下步骤执行：

## 步骤1：修改writer_sys.go

读取 msgdb-dump/dump/writer_sys.go，然后进行以下修改：

### 1.1 新增insertProviderMessagesBatch函数

这个函数负责将消息写入provider_messages表，按provider_name分组写入：

```go
// insertProviderMessagesBatch inserts messages for a specific provider into provider_messages.
// Each provider gets its own copy of messages to avoid cross-provider conflicts.
func insertProviderMessagesBatch(db *sql.DB, providerName string, dllID int64, lang string, messages []PeMessage) error {
    if len(messages) == 0 {
        return nil
    }

    const chunkSize = 500

    for start := 0; start < len(messages); start += chunkSize {
        end := start + chunkSize
        if end > len(messages) {
            end = len(messages)
        }
        chunk := messages[start:end]

        stmt := "INSERT OR IGNORE INTO provider_messages " +
            "(provider_name, dll_id, lang, event_id, message, level, task, opcode, keywords, parameters, level_name, keywords_name) VALUES "

        for i, msg := range chunk {
            if i > 0 {
                stmt += ", "
            }

            var paramsJSON string
            if msg.Parameters != nil {
                b, err := json.Marshal(*msg.Parameters)
                if err != nil {
                    return fmt.Errorf("failed to marshal parameters for event %d: %w", msg.EventID, err)
                }
                paramsJSON = string(b)
            }

            stmt += fmt.Sprintf("('%s',%d,'%s',%d,'%s',%s,%s,%s,%s,%s,%s,%s)",
                escapeSQL(providerName),
                dllID,
                escapeSQL(lang),
                msg.EventID,
                escapeSQL(msg.Message),
                optU8SQL(msg.Level),
                optStrSQL(msg.Task),
                optStrSQL(msg.Opcode),
                optStrSQL(msg.Keywords),
                optStrPtr(&paramsJSON, msg.Parameters == nil),
                optStrSQL(msg.LevelName),
                optStrSQL(msg.KeywordsName),
            )
        }

        if _, err := db.Exec(stmt); err != nil {
            return fmt.Errorf("failed to batch insert provider_messages for %s: %w", providerName, err)
        }
    }

    return nil
}
```

### 1.2 修改CreateSystemDB函数

将CreateSystemDB改为使用V5 Schema：

1. 导入schema包（已存在）
2. 将schema.SchemaV4DDL改为schema.SchemaV5DDL
3. 将schema.SchemaV4Indexes改为schema.SchemaV5Indexes
4. 修改消息写入逻辑：为每个Provider写一份消息

关键修改：
```go
// 原来的写入（V4）：
for lang, msgs := range group.MessagesByLang {
    if err := insertDLLMessagesBatch(db, dllID, lang, msgs); err != nil {
        return err
    }
}

// 新的写入（V5）：
for _, provider := range group.Providers {
    for lang, msgs := range group.MessagesByLang {
        if err := insertProviderMessagesBatch(db, provider.Name, dllID, lang, msgs); err != nil {
            return err
        }
    }
}
```

5. 更新schema_version为"5"
6. 删除fixOrphanedMessages调用（V5不再需要）

## 步骤2：创建V5 Schema测试

读取 msgdb-dump/schema/v4_test.go，然后创建 msgdb-dump/schema/v5_test.go：

```go
package schema

import (
    "strings"
    "testing"
)

func TestSchemaV5DDL_ContainsAllTables(t *testing.T) {
    expectedTables := []string{
        "dll_entries",
        "provider_messages",
        "metadata",
        "parameter_refs",
        "providers",
        "value_maps",
    }
    for _, name := range expectedTables {
        if !strings.Contains(SchemaV5DDL, "CREATE TABLE IF NOT EXISTS "+name) {
            t.Errorf("SchemaV5DDL missing table: %s", name)
        }
    }
}

func TestSchemaV5DDL_ProviderMessagesPK(t *testing.T) {
    if !strings.Contains(SchemaV5DDL, "PRIMARY KEY (provider_name, lang, event_id, dll_id)") {
        t.Error("provider_messages should have composite PK (provider_name, lang, event_id, dll_id)")
    }
}

func TestSchemaV5Indexes_ContainsAllIndexes(t *testing.T) {
    expectedIndexes := []string{
        "idx_provider_messages_eid",
        "idx_provider_messages_provider",
        "idx_provider_messages_dll",
        "idx_providers_dll",
    }
    for _, name := range expectedIndexes {
        if !strings.Contains(SchemaV5Indexes, "CREATE INDEX IF NOT EXISTS "+name) {
            t.Errorf("SchemaV5Indexes missing index: %s", name)
        }
    }
}

func TestSchemaV5CompatView_ContainsView(t *testing.T) {
    if !strings.Contains(SchemaV5CompatView, "CREATE VIEW IF NOT EXISTS dll_messages AS") {
        t.Error("SchemaV5CompatView should create dll_messages view")
    }
}
```

## 步骤3：更新writer_sys_test.go

读取 msgdb-dump/dump/writer_sys_test.go，然后更新测试：

1. 将所有对dll_messages的引用改为provider_messages
2. 更新期望的表名列表
3. 更新查询语句

关键修改：
- expectedTables: 移除"dll_messages"，添加"provider_messages"
- countRows检查：改为检查provider_messages
- 查询语句：直接查provider_messages，不需要JOIN

## 执行顺序

1. 先读取相关文件了解当前实现
2. 修改writer_sys.go
3. 创建v5_test.go
4. 更新writer_sys_test.go
5. 运行测试验证：cd msgdb-dump && go test ./...

完成后报告修改的文件列表和测试结果。

